from connect import ConnectGame


class ConnectGameTests(unittest.TestCase):
    def test_empty_boards(self):
        for board in ("", " \n\t", ".", ". .\n . ."):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_single_stones(self):
        for player in ("X", "O"):
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(player).get_winner(), player)

    def test_horizontal_x_connection(self):
        self.assertEqual(ConnectGame("O . . .\n X X X X").get_winner(), "X")

    def test_vertical_o_connection(self):
        self.assertEqual(ConnectGame(". O\n X O\n . O\n X O").get_winner(), "O")

    def test_connections_to_wrong_sides_do_not_win(self):
        for board in ("O O O\n . . .", "X .\n X .\n X ."):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_example_has_no_winner(self):
        board = """
. O . X .
 . X X O .
  O O O X .
   . X O X O
    X O O O X
"""
        self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_up_right_diagonal_connects_x(self):
        self.assertEqual(ConnectGame(". . X\n . X .\n X . .").get_winner(), "X")

    def test_down_left_diagonal_connects_o(self):
        self.assertEqual(ConnectGame(". . O\n . O .\n O . .").get_winner(), "O")

    def test_down_right_diagonal_does_not_connect(self):
        for player in ("X", "O"):
            board = f"{player} . .\n . {player} .\n . . {player}"
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_all_starting_stones_are_considered(self):
        self.assertEqual(ConnectGame("X . .\n . . .\n X X X").get_winner(), "X")
        self.assertEqual(ConnectGame("O . O\n . . O\n . . O").get_winner(), "O")

    def test_single_row_and_single_column(self):
        for board, expected in (
            (". O .", "O"),
            ("X X X", "X"),
            (".\nX\n.", "X"),
            ("O\nO\nO", "O"),
        ):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), expected)

    def test_cycles_without_a_winning_connection(self):
        board = "X X . .\n X X . .\n . . . ."
        self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_long_path_does_not_require_recursion(self):
        board = "\n".join(["O"] * 1500)
        game = ConnectGame(board)
        self.assertEqual(game.get_winner(), "O")
        self.assertEqual(game.get_winner(), "O")


if __name__ == "__main__":
    unittest.main()
